package br.com.aniversarios;
import android.app.*; import android.appwidget.*; import android.content.*; import android.os.*; import android.view.*; import android.widget.*; import java.time.*; import java.time.format.*; import org.json.*;
public class MainActivity extends Activity {
 JSONArray people; LinearLayout root; final DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd/MM/uuuu").withResolverStyle(ResolverStyle.STRICT);
 public void onCreate(Bundle b){super.onCreate(b);show();}
 protected void onResume(){super.onResume();show();BirthdayWidget.refresh(this);}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xFFFFFFFF);t.setPadding(0,12,0,12);return t;}
 void button(String s,Runnable fn){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->fn.run());root.addView(b);}
 void show(){people=Store.read(this);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,48,24,32);root.setBackgroundColor(0xFF202325);scroll.addView(root);setContentView(scroll);root.addView(label("Aniversários",30));root.addView(label("O tempo de quem faz parte da sua vida",15));
 for(int n=0;n<people.length();n++){final int index=n;JSONObject o=people.optJSONObject(n);if(o==null)continue;String text=o.optString("name");try{LocalDate d=LocalDate.parse(o.getString("date"));text+="\n"+Age.between(d,LocalDate.now())+"\n"+d.format(fmt);}catch(Exception e){text+="\nConfira a data";}TextView t=label(text,18);t.setBackgroundResource(R.drawable.glass);t.setPadding(20,20,20,20);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=16;root.addView(t,lp);t.setOnClickListener(v->edit(index));}
 button("＋ Cadastrar aniversário",()->edit(-1));button("Adicionar widget à tela inicial",()->{AppWidgetManager m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,BirthdayWidget.class),null,null);else new AlertDialog.Builder(this).setMessage("Na tela inicial, pressione uma área vazia, escolha Widgets e procure Aniversários.").setPositiveButton("Entendi",null).show();});root.addView(label("Toque em uma pessoa para editar ou excluir.\nDados salvos neste aparelho. Desinstalar apaga os cadastros.\nO widget exibe duas pessoas por página; aumente sua altura se necessário.",13));}
 void edit(int index){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(32,8,32,8);EditText name=new EditText(this);name.setHint("Nome ou título");name.setSingleLine(true);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});EditText date=new EditText(this);date.setHint("Data de nascimento · DD/MM/AAAA");date.setInputType(android.text.InputType.TYPE_CLASS_DATETIME|android.text.InputType.TYPE_DATETIME_VARIATION_DATE);form.addView(name);form.addView(date);if(index>=0){JSONObject o=people.optJSONObject(index);name.setText(o.optString("name"));try{date.setText(LocalDate.parse(o.getString("date")).format(fmt));}catch(Exception ignored){}}
 AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(index<0?"Novo aniversário":"Editar aniversário").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",null);
 if(index>=0)builder.setNeutralButton("Excluir",(d,w)->new AlertDialog.Builder(this).setMessage("Excluir este aniversário?").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(x,y)->{people.remove(index);Store.save(this,people);show();}).show());
 AlertDialog dialog=builder.create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String title=name.getText().toString().trim();if(title.isEmpty()){name.setError("Informe um nome");return;}try{LocalDate birth=LocalDate.parse(date.getText().toString().trim(),fmt);if(birth.getYear()<1||birth.isAfter(LocalDate.now()))throw new IllegalArgumentException();JSONObject o=new JSONObject().put("name",title).put("date",birth.toString());if(index<0)people.put(o);else people.put(index,o);Store.save(this,people);dialog.dismiss();show();}catch(Exception e){date.setError("Use uma data válida, até hoje: DD/MM/AAAA");}}));dialog.show(); }
}
